WITH base AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, DATE_SUB(starts_on, 76) AS starts_on_minus_76d, ROUND(discount_pct, 2) AS discount_pct_rounded FROM promotions WHERE starts_on >= DATE '2023-08-03' AND discount_pct >= 0.2) SELECT * FROM (SELECT channel, promo_code, discount_pct_rounded FROM base) src PIVOT (AVG(discount_pct_rounded) AS value_sum, COUNT(1) AS cnt FOR promo_code IN ('WELCOME5' AS welcome5, 'VIP' AS vip))
